def anti_dump():
    try:
        sys.dont_write_bytecode = True
    except:
        pass

def anti_decrypt():
    try:
        for f in inspect.stack():
            if any((x in f.filename.lower() for x in ["dump", "trace", "debug"])):
                peler()
    except:
        pass

def anti_log():
    try:
        if sys.stdout != sys.__stdout__:
            peler()
    except:
        pass

def anti_reverse():
    try:
        for v in os.environ.values():
            v = v.lower()
            for x in ["ida", "ghidra", "radare", "x64dbg"]:
                if x in v:
                    peler()
    except:
        pass

def anti_crack():
    try:
        import hashlib
        h = hashlib.sha256(inspect.getsource(anti_crack).encode()).hexdigest()
        if len(h) != 64:
            peler()
    except:
        pass

def detect_root():
    if not sys.platform.startswith("linux"):
        return
    try:
        for p in ["/system/bin/su", "/system/xbin/su", "/sbin/su"]:
            if os.path.exists(p):
                peler()
    except:
        pass

def detect_vm():
    if not sys.platform.startswith("linux"):
        return
    try:
        cpu = open("/proc/cpuinfo").read().lower()
        for k in ["vmware", "virtualbox", "qemu", "goldfish", "emulator"]:
            if k in cpu:
                peler()
    except:
        pass
        
def anti_tracker():
    if not sys.platform.startswith("linux"):
        return
    try:
        with open("/proc/self/status", "r") as f:
            status = f.read()
            if "TracerPid:" in status:
                tracer = status.split("TracerPid:")[1].split()[0]
                if tracer != "0":
                    peler()
        for pid in os.listdir('/proc'):
            if pid.isdigit():
                try:
                    exe = os.readlink(f'/proc/{{pid}}/exe')
                    if "strace" in exe or "ltrace" in exe:
                        peler()
                except:
                    continue
    except:
        pass

def anti_hook():
    try:
        for f in ["exec", "eval", "open", "__import__"]:
            if getattr(builtins, f) != getattr(__builtins__, f):
                peler()
    except:
        pass

def anti_hex():
    try:
        if bytes.fromhex('41') != b'A' or __import__('binascii').unhexlify('41') != b'A':
            peler()
    except:
        peler()

